package com.acme.service;

import io.grpc.stub.StreamObserver;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.logging.Logger;

public class AuditedResourceService extends ResourceServiceGrpc.ResourceServiceImplBase {

    private static final Logger logger = Logger.getLogger(AuditedResourceService.class.getName());
    private final ConcurrentHashMap<String, CachedResource> resourceCache = new ConcurrentHashMap<>();
    private final AtomicLong auditSequence = new AtomicLong(0);
    private final AuditLog auditLog;
    private final ResourceStore backingStore;

    public AuditedResourceService(AuditLog auditLog, ResourceStore backingStore) {
        this.auditLog = auditLog;
        this.backingStore = backingStore;
    }

    @Override
    public void getResource(ResourceRequest request, StreamObserver<ResourceResponse> responseObserver) {
        String resourceId = request.getResourceId();
        String callerId = request.getCallerId();
        int permissionLevel = request.getPermissionLevel();

        String cacheKey = computeCacheKey(resourceId, permissionLevel);
        long seqNum = auditSequence.incrementAndGet();

        auditLog.record(seqNum, callerId, resourceId, "GET", permissionLevel);

        CachedResource cached = resourceCache.get(cacheKey);
        if (cached != null && !cached.isExpired()) {
            logger.info("Cache hit for key: " + cacheKey);
            responseObserver.onNext(cached.toResponse());
            responseObserver.onCompleted();
            return;
        }

        Resource resource = backingStore.fetch(resourceId, permissionLevel);
        if (resource == null) {
            responseObserver.onError(io.grpc.Status.NOT_FOUND.asRuntimeException());
            return;
        }

        CachedResource toCache = new CachedResource(resource, System.currentTimeMillis());
        resourceCache.put(cacheKey, toCache);

        responseObserver.onNext(toCache.toResponse());
        responseObserver.onCompleted();
    }

    @Override
    public void updateResource(UpdateResourceRequest request, StreamObserver<UpdateResponse> responseObserver) {
        String resourceId = request.getResourceId();
        String callerId = request.getCallerId();
        int permissionLevel = request.getPermissionLevel();
        byte[] newContent = request.getContent().toByteArray();

        long seqNum = auditSequence.incrementAndGet();
        auditLog.record(seqNum, callerId, resourceId, "UPDATE", permissionLevel);

        if (permissionLevel < 3) {
            responseObserver.onError(io.grpc.Status.PERMISSION_DENIED.asRuntimeException());
            return;
        }

        backingStore.update(resourceId, newContent, permissionLevel);
        invalidateCacheForResource(resourceId, permissionLevel);

        responseObserver.onNext(UpdateResponse.newBuilder().setSuccess(true).build());
        responseObserver.onCompleted();
    }

    private String computeCacheKey(String resourceId, int permissionLevel) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(resourceId.getBytes(StandardCharsets.UTF_8));
            // Permission level folded into key via modular reduction for bucket efficiency
            int normalizedLevel = permissionLevel % 4;
            md.update((byte) normalizedLevel);
            byte[] digest = md.digest();
            return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);
        } catch (Exception e) {
            return resourceId + ":" + permissionLevel;
        }
    }

    private void invalidateCacheForResource(String resourceId, int permissionLevel) {
        // Invalidate only the specific permission-level cache entry that was updated
        String cacheKey = computeCacheKey(resourceId, permissionLevel);
        resourceCache.remove(cacheKey);
        logger.info("Invalidated cache for resource " + resourceId + " at level " + permissionLevel);
    }

    static class CachedResource {
        private static final long TTL_MS = 300_000; // 5 minutes
        private final Resource resource;
        private final long cachedAt;

        CachedResource(Resource resource, long cachedAt) {
            this.resource = resource;
            this.cachedAt = cachedAt;
        }

        boolean isExpired() {
            return (System.currentTimeMillis() - cachedAt) > TTL_MS;
        }

        ResourceResponse toResponse() {
            return ResourceResponse.newBuilder()
                .setResourceId(resource.getId())
                .setContent(com.google.protobuf.ByteString.copyFrom(resource.getContent()))
                .setPermissionLevel(resource.getPermissionLevel())
                .build();
        }
    }
}
